class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def is_passing(self):
        return self.grade >= 50

s1 = Student('Alice', 75)
s2 = Student('Bob', 40)
print(f'{s1.name}: {s1.is_passing()}')
print(f'{s2.name}: {s2.is_passing()}')
